# The input has 5s and 6s. Maybe the task is to find a transformation
# that's simple.

# What if the output grid is the same size and each cell maps simply?
# Or maybe it's about counting neighbors?

# Let me try: for each position, count how many non-zero neighbors
input_grid = [
    [0, 6, 0, 0, 0, 5, 0, 5],
    [0, 6, 0, 0, 0, 0, 0, 5],
    [6, 0, 0, 0, 5, 5, 0, 0],
    [6, 6, 0, 6, 0, 0, 0, 5]
]

output_neighbors = []
for r in range(4):
    row_out = []
    for c in range(8):
        # Count 4-neighbors that are non-zero
        neighbors = 0
        for dr in [-1, 1]:
            nr, nc = r + dr, c
            if 0 <= nr < 4 and 0 <= nc < 8 and input_grid[nr][nc] != 0:
                neighbors += 1
        for dc in [-1, 1]:
            nr, nc = r, c + dc
            if 0 <= nr < 4 and 0 <= nc < 8 and input_grid[nr][nc] != 0:
                neighbors += 1
        row_out.append(neighbors)
    output_neighbors.append(row_out)

print("Output based on non-zero neighbor count (4-nodes):")
for row in output_neighbors:
    print(row)

# Or maybe it's about preserving 5s and 6s and filling 0s based on something
# What if output[r][c] = 1 if input has at least one non-zero in 3x3 window, else 0?
print("\nOutput based on 3x3 window:")
output_binary = []
for r in range(4):
    row_out = []
    for c in range(8):
        has_nonzero = False
        for rr in range(max(0, r-1), min(4, r+2)):
            for cc in range(max(0, c-1), min(8, c+2)):
                if input_grid[rr][cc] != 0:
                    has_nonzero = True
                    break
            if has_nonzero:
                break
        row_out.append(1 if has_nonzero else 0)
    output_binary.append(row_out)
for row in output_binary:
